from common import *
import pandas as pd
O=ROOT/"phase88";pr=json.loads((O/"protocol.json").read_text());done=json.loads((O/"complete.json").read_text());assert done["status"]=="PASS";cw=np.array(json.loads((ROOT/"phase36/mixed_class_weights.json").read_text())["balanced_weights"]);sourceaudit=[];directions={}
for which in pr["heads"]:
 a=np.load(O/(which+"_source_directions.npz"));updates=a["updates"].astype(float);ss=a["subjects"];mean=np.mean([updates[ss==sid].mean(0) for sid in pr["meta_subjects"]],axis=0);err=float(abs(mean-a["mean"]).max());assert err<1e-15;assert updates.shape==(317,9600);assert (np.linalg.norm(updates,axis=1)<.01001).all()
 cos=updates@mean/(np.linalg.norm(updates,axis=1)*np.linalg.norm(mean));sourceaudit.append(dict(head=which,equal_person_mean_error=err,source_mean_norm=float(np.linalg.norm(mean)),source_update_to_mean_cosine_mean=float(cos.mean()),source_update_to_mean_cosine_median=float(np.median(cos)),source_update_to_mean_cosine_min=float(cos.min())));directions[which]=mean
mean_cos=float(directions["future"]@directions["current"]/(np.linalg.norm(directions["future"])*np.linalg.norm(directions["current"])))
rows=[];maxerr=0.;normerr=0.
for group,sids in pr["evaluation_groups"].items():
 for sid in sids:
  d=json.loads((O/f"s{sid:02d}.json").read_text());assert len(d["rows"])==256
  for r in d["rows"]:
   b=np.array(r["future_base_probabilities"]);w=np.array(r["future_write_probabilities"]);y=np.array(r["future_labels"]);assert (b>0).all() and (w>0).all();gain=np.log(w[np.arange(4),y])-np.log(b[np.arange(4),y]);err=abs(float(gain.mean())-r["future_ce_gain"]);maxerr=max(maxerr,err);assert err<1e-12 and abs(float((gain*cw[y]).mean())-r["balanced_ce_gain"])<1e-12
   bp=b.argmax(1);wp=w.argmax(1);assert int(((bp!=y)&(wp==y)).sum())==r["corrected"];assert int(((bp==y)&(wp!=y)).sum())==r["harmed"]
   if r["variant"]=="source_mean_normmatched_current":normerr=max(normerr,abs(r["actual_update_norm"]-r["dynamic_update_norm"]))
   rows.append({k:v for k,v in r.items() if k not in ["future_labels","future_base_probabilities","future_write_probabilities"]})
df=pd.DataFrame(rows);assert len(df)==2048 and normerr<1e-6;df["dynamic_minus_fixed_ce"]=df.dynamic_future_ce_gain-df.future_ce_gain;df["dynamic_minus_fixed_balanced_ce"]=df.dynamic_balanced_ce_gain-df.balanced_ce_gain;df.to_csv(O/"pulses.csv",index=False)
person=df.groupby(["group","subject","head","variant"]).agg(future_ce_gain=("future_ce_gain","mean"),balanced_ce_gain=("balanced_ce_gain","mean"),dynamic_future_ce_gain=("dynamic_future_ce_gain","mean"),dynamic_minus_fixed_ce=("dynamic_minus_fixed_ce","mean"),dynamic_minus_fixed_balanced_ce=("dynamic_minus_fixed_balanced_ce","mean"),corrected=("corrected","sum"),harmed=("harmed","sum")).reset_index();person.to_csv(O/"people.csv",index=False)
summary=person.groupby(["group","head","variant"]).agg(fixed_future_ce_gain=("future_ce_gain","mean"),fixed_balanced_ce_gain=("balanced_ce_gain","mean"),dynamic_future_ce_gain=("dynamic_future_ce_gain","mean"),dynamic_minus_fixed_ce=("dynamic_minus_fixed_ce","mean"),dynamic_positive_people=("dynamic_minus_fixed_ce",lambda v:int((v>0).sum())),fixed_positive_people=("future_ce_gain",lambda v:int((v>0).sum())),corrected=("corrected","sum"),harmed=("harmed","sum"));summary.to_csv(O/"summary.csv")
audit=dict(status="PASS",source=sourceaudit,future_current_source_mean_direction_cosine=mean_cos,rows=2048,max_ce_error=maxerr,max_normmatch_error=normerr,no_extra_class_labels=True,prior_phase87_failed_gate_unchanged=True,not_online_validation=True);(O/"audit.json").write_text(json.dumps(audit,indent=2))
(O/"report.html").write_text('<!doctype html><meta charset="utf-8"><style>body{font:16px/1.6 sans-serif;max-width:1450px;margin:35px auto}td,th{padding:6px;border:1px solid #ddd}</style><h1>元训练写入机制：固定源修正能解释多少收益？</h1><p>这是phase87结果后的机制分析，不改其失败门槛。每个已训练辅助头在原五位元训练者的317个片段上产生单次更新，按人等权平均得到一个固定参数偏移。它无需目标片段重建或目标标签，可以在推理前一次性应用。第二个对照只沿该固定方向，幅度匹配真实当前片段写入的可观测范数。</p><p>这些修正仍继承辅助头训练的标签成本：后续目标1,268、当前目标317；额外标签为0。比较同一人、同一时点、同一基础分类器的后续4段效用。动态减固定为正才表示动态方向具有额外优势。仅限源人群已观察样本、冷启动单步分析，不能代替持续在线或新目标验证。</p>'+summary.reset_index().to_html(index=False,float_format=lambda x:f"{x:.8f}")+'<h2>源方向结构</h2>'+pd.DataFrame(sourceaudit).to_html(index=False,float_format=lambda x:f"{x:.8f}")+f'<p>后续目标与当前目标的平均源方向余弦：{mean_cos:.8f}。方向相近本身不是分类收益或因果证明。</p><p><a href="audit.json">独立审计</a> · <a href="people.csv">逐人比较</a> · <a href="../phase87/report.html">保留原始失败结果</a></p>')
print(summary.to_string());print(sourceaudit);print("Mean directions cosine",mean_cos);print(audit)
